(6255038, 924701, 114225, '<td valign="top">I like you idea here, and the monotone gives it a nicer classic feel. But I would have liked to see a bit more contrast in the photo.</td>', 'I like you idea here, and the monotone gives it a nicer classic feel. But I would have liked to see a bit more contrast in the photo.', '2010-12-15 19:28:39.000000', NULL, 1),
(6255041, 925098, 114225, '<td valign="top">Um, is this photo of my house?!? The blinds, ceiling lighting, and mantle photo all look very similar. Creepy!<br/> <br/>I''m not seeing how this really fits the challenge all that well. Are you shopping for ghosts?</td>', 'Um, is this photo of my house?!? The blinds, ceiling lighting, and mantle photo all look very similar. Creepy! I''m not seeing how this really fits the challenge all that well. Are you shopping for ghosts?', '2010-12-15 19:30:18.000000', NULL, 1),
(6255044, 924684, 114225, '<td valign="top">Nice colors in this photo. I would like to have seen more detail on the outside of the store to add context.</td>', 'Nice colors in this photo. I would like to have seen more detail on the outside of the store to add context.', '2010-12-15 19:30:51.000000', NULL, 1),
(6255046, 924808, 114225, '<td valign="top">Great shot. A bit busy with all the stuff in there, but that''s part of makes this good.</td>', 'Great shot. A bit busy with all the stuff in there, but that''s part of makes this good.', '2010-12-15 19:32:47.000000', NULL, 1),
(6255047, 925215, 114225, '<td valign="top">Nice capture of the season. I like the name of this store quite a bit. I think I would have liked a tighter crop so we could focus more on the window than the surroundings (of course, a bit of surroundings is good to setup context).</td>', 'Nice capture of the season. I like the name of this store quite a bit. I think I would have liked a tighter crop so we could focus more on the window than the surroundings (of course, a bit of surroundings is good to setup context).', '2010-12-15 19:33:43.000000', NULL, 1),
(6255048, 925005, 114225, '<td valign="top">Hmmm, I''m not really feeling this photo. the reflection of the car is distracting away from the lamp (which feels like it should be the main subject). Plus, window shopping is a term that implies you are shopping from the outside instead of the inside.</td>', 'Hmmm, I''m not really feeling this photo. the reflection of the car is distracting away from the lamp (which feels like it should be the main subject). Plus, window shopping is a term that implies you are shopping from the outside instead of the inside.', '2010-12-15 19:34:58.000000', NULL, 1),
(6255075, 925157, 114225, '<td valign="top">Well, I get your idea, but am not too fond of the shot.</td>', 'Well, I get your idea, but am not too fond of the shot.', '2010-12-15 20:08:41.000000', NULL, 1),
(6255077, 925008, 114225, '<td valign="top">Nice choice for subject this time of year. I like the classic-type look this has with dull colors.</td>', 'Nice choice for subject this time of year. I like the classic-type look this has with dull colors.', '2010-12-15 20:09:27.000000', NULL, 1),
