(6255175, 925204, 114225, '<td valign="top">Nice timing/idea. Good clean details. The center composition seems to work here.</td>', 'Nice timing/idea. Good clean details. The center composition seems to work here.', '2010-12-15 21:31:29.000000', NULL, 1),
(6255176, 924749, 114225, '<td valign="top">Great choice of subject matter for this. I''m glad you included the text on the bottom, that adds some interest.</td>', 'Great choice of subject matter for this. I''m glad you included the text on the bottom, that adds some interest.', '2010-12-15 21:32:05.000000', NULL, 1),
(6255177, 925093, 114225, '<td valign="top">I like the way you included a bit of the door frame for context. I think this could have been a good chance to get more of a pose from the shopkeep. Bring a bit of emotion to the photo.</td>', 'I like the way you included a bit of the door frame for context. I think this could have been a good chance to get more of a pose from the shopkeep. Bring a bit of emotion to the photo.', '2010-12-15 21:33:31.000000', NULL, 1),
